import{_ as p,a0 as r,w as a,s as u,I as e,x as i,a1 as o,A as s,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 1.0 之旅：回顧這一切的開始 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 1.0 之旅：回顧這一切的開始 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 1.0 之旅：回顧這一切的開始 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 1.0 之旅：回顧這一切的開始 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170825 Happy anniversary Linux A look back at where it all began","title":"Linux 1.0 之旅：回顧這一切的開始","tag":"201709","desc":""},"relativePath":"201709/20170825 Happy anniversary Linux A look back at where it all began.md","filePath":"[post].md"}'),m={name:"201709/20170825 Happy anniversary Linux A look back at where it all began.md"};function d(f,t,g,x,S,L){const n=r("Link");return a(),u("div",null,[t[43]||(t[43]=e("h1",{id:"linux-1-0-之旅-回顧這一切的開始",tabindex:"-1"},[i("Linux 1.0 之旅：回顧這一切的開始 "),e("a",{class:"header-anchor",href:"#linux-1-0-之旅-回顧這一切的開始","aria-label":"Permalink to “Linux 1.0 之旅：回顧這一切的開始”"},"​")],-1)),t[44]||(t[44]=e("blockquote",null,[e("p",null,"通過安裝 SLS 1.05 展示了 Linux 內核在這 26 年間走過了多遠。")],-1)),t[45]||(t[45]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/happy_birthday_tux.png?itok=GoaC0Car",alt:"Happy anniversary, Linux: A look back at where it all began",title:"Happy anniversary, Linux: A look back at where it all began"})],-1)),e("p",null,[t[1]||(t[1]=i("我第一次安裝 Linux 是在 1993 年。那時我跑的是 MS-DOS，但我真的很喜歡學校機房電腦的 Unix 系統，就在那裏度過了我大學本科時光。 當我聽説了 Linux，一個 Unix 的免費版本，可以在我家的 386 電腦上運行的時候，我立刻就想要試試。我的第一個 Linux 發行版是 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/Softlanding_Linux_System"},{default:s(()=>[...t[0]||(t[0]=[i("Softlanding Linux System",-1)])]),_:1}),t[2]||(t[2]=i(" (SLS) 1.03，帶有 11 級補丁的 0.99 alpha 版本的 Linux 內核。它要求高達 2 MB 的內存，如果你想要編譯項目需要 4 MB，運行 X windows 則需要 8 MB。",-1))]),t[46]||(t[46]=l('<p>我認為 Linux 相較於 MS-DOS 世界是一個巨大的進步。 儘管 Linux 缺乏運行在 MS-DOS 上的廣泛的應用及遊戲，但我發現 Linux 帶給我的是巨大的靈活性。不像 MS-DOS ，現在我可以進行真正的多任務，同時運行不止一個程序。並且 Linux 提供了豐富的工具，包括一個 C 語言編譯器，讓我可以構建自己的項目。</p><p>一年後，我升級到了 SLS 1.05，它支持全新的 Linux 內核 1.0。 更重要的，Linux 引入了內核模組。通過內核模組，你不再需要為支持新硬件而編譯整個內核；取而代之，只需要從包含 Linux 內核之內的 63 個模組里加載一個就行。在 SLS 1.05 的發行自述文件中包含這些關於模組的註釋：</p><blockquote><p>內核的模組化旨在正視減少並最終消除重新編譯內核的要求，無論是變更、修改設備驅動或者為了動態訪問不常用的驅動。也許更為重要的是，個別工作小組的工作不再影響到內核的正確開發。事實上，這讓以二進制發佈官方內核現在成為了可能。</p></blockquote><p>在 8 月 25 日，Linux 內核將迎來它的第 26 週年（LCTT 譯註：已經過去了 =.= ）。為了慶祝，我重新安裝了 SLS 1.05 來提醒自己 Linux 1.0 內核是什麼樣子，去認識 Linux 自二十世紀 90 年代以來走了多遠。和我一起踏上 Linux 的懷舊之旅吧！</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>SLS 是第一個真正的 “發行版”，因為它包含一個安裝程序。 儘管安裝過程並不像現代發行版一樣順暢。 不能從 CD-ROM 啓動安裝，我需要從安裝軟盤啓動我的系統，然後從 <strong>login</strong> 提示中運行安裝程序。</p><p><img src="https://opensource.com/sites/default/files/u128651/install1.png" alt="Installing SLS 1.05 from the login prompt" title="Installing SLS 1.05 from the login prompt"></p><p>在 SLS 1.05 中引入的一個漂亮的功能是支持彩色的文本模式安裝器。當我選擇彩色模式時，安裝器切換到一個帶有黑色文字的亮藍色背景，不再是我們祖祖輩輩們使用的原始的普通黑白文本。</p><p><img src="https://opensource.com/sites/default/files/u128651/install2.png" alt="Color-enabled text-mode installer in SLS 1.05" title="Color-enabled text-mode installer in SLS 1.05"></p><p>SLS 安裝器是個簡單的東西，文本從屏幕底部滾動而上，顯示其做的工作。通過對一些簡單的提示的響應，我能夠創建一個 Linux 分區，掛載上 ext2 文件系統，並安裝 Linux 。 安裝包含了 X windows 和開發工具的 SLS 1.05，需要大約 85 MB 的磁盤空間。依照今天的標準這聽起來可能不是很多，但在 Linux 1.0 出來的時候，120 MB 的硬件設備才是主流設備。</p><p><img src="https://opensource.com/sites/default/files/u128651/install10.png" alt="Creating a partition for Linux, putting an ext2 filesystem on it, and installing Linux" title="Creating a partition for Linux, putting an ext2 filesystem on it, and installing Linux"></p><p><img src="https://opensource.com/sites/default/files/u128651/firstboot1.png" alt="First boot" title="First boot"></p><h3 id="系統級別" tabindex="-1">系統級別 <a class="header-anchor" href="#系統級別" aria-label="Permalink to “系統級別”">​</a></h3><p>當我第一次啓動到 Linux 時，讓我想起來了一些關於這個早期版本 Linux 系統的事情。首先，Linux 沒有佔據很多的空間。在啓動系統之後運行一些程序來檢查的時候，Linux 佔用了不到 4 MB 的內存。在一個擁有 16MB 內存的系統中，這就意味着節省了很多內存用來運行程序。</p><p><img src="https://opensource.com/sites/default/files/u128651/uname-df.png" alt="Checking out the filesystem and available disk space" title="Checking out the filesystem and available disk space"></p><p>熟悉的 <code>/proc</code> 元文件系統在 Linux 1.0 就存在了，儘管對比我們今天在現代系統上看到的，它並不能提供許多信息。在 Linux 1.0， <code>/proc</code> 包含一些接口來探測類似 <code>meminfo</code> 和 <code>stat</code> 之類的基本系統狀態。</p><p><img src="https://opensource.com/sites/default/files/u128651/proc.png" alt="The familiar /proc meta filesystem" title="The familiar /proc meta filesystem"></p>',17)),e("p",null,[t[6]||(t[6]=i("在這個系統上的 ",-1)),t[7]||(t[7]=e("code",null,"/etc",-1)),t[8]||(t[8]=i(" 文件目錄非常簡單。值得一提的是，SLS 1.05 借用了來自 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/Berkeley_Software_Distribution"},{default:s(()=>[...t[3]||(t[3]=[i("BSD Unix",-1)])]),_:1}),t[9]||(t[9]=i(" 的 ",-1)),t[10]||(t[10]=e("strong",null,"rc",-1)),t[11]||(t[11]=i(" 腳本來控制系統啓動。 初始化是通過 ",-1)),t[12]||(t[12]=e("strong",null,"rc",-1)),t[13]||(t[13]=i(" 腳本進行的，由 ",-1)),t[14]||(t[14]=e("code",null,"rc.local",-1)),t[15]||(t[15]=i(" 文件來定義本地系統的調整。後來，許多 Linux 發行版採用了來自 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/UNIX_System_V"},{default:s(()=>[...t[4]||(t[4]=[i("Unix System V",-1)])]),_:1}),t[16]||(t[16]=i(" 的很相似的 ",-1)),t[17]||(t[17]=e("strong",null,"init",-1)),t[18]||(t[18]=i(" 腳本，後來又是 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/Systemd"},{default:s(()=>[...t[5]||(t[5]=[i("systemd",-1)])]),_:1}),t[19]||(t[19]=i(" 初始化系統。",-1))]),t[47]||(t[47]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/u128651/etc.png",alt:"The /etc directory",title:"The /etc directory"})],-1)),t[48]||(t[48]=e("h3",{id:"你能做些什麼",tabindex:"-1"},[i("你能做些什麼 "),e("a",{class:"header-anchor",href:"#你能做些什麼","aria-label":"Permalink to “你能做些什麼”"},"​")],-1)),t[49]||(t[49]=e("p",null,"隨着我的系統的啓動運行，接下來就可以使用了了。那麼，在這樣的早期 Linux 系統上你能做些什麼？",-1)),e("p",null,[t[22]||(t[22]=i("讓我們從基本的文件管理開始。 每次在你登錄的時候，SLS 會讓你使用 Softlanding 菜單界面（MESH），這是一個文件管理程序，現代的用户們可能覺得它和 ",-1)),o(n,{href:"https://midnight-commander.org/"},{default:s(()=>[...t[20]||(t[20]=[i("Midnight Commander",-1)])]),_:1}),t[23]||(t[23]=i(" 很相似。 而二十世紀 90 年代的用户們可能會拿 MESH 與更為接近的 ",-1)),o(n,{href:"https://en.wikipedia.org/wiki/Norton_Commander"},{default:s(()=>[...t[21]||(t[21]=[i("Norton Commander",-1)])]),_:1}),t[24]||(t[24]=i(" 相比，這個可以説是在 MS-DOS 上最流行的第三方文件管理程序。",-1))]),t[50]||(t[50]=l('<p><img src="https://opensource.com/sites/default/files/u128651/mesh.png" alt="The Softlanding menu shell (MESH)" title="The Softlanding menu shell (MESH)"></p><p>除了 MESH 之外，在 SLS 1.05 中還少量包含了一些全屏應用程序。你可以找到熟悉的用户工具，包括 Elm 郵件閲讀器、GNU Emacs 可編程編輯器，以及古老的 Vim 編輯器。</p><p><img src="https://opensource.com/sites/default/files/u128651/elm.png" alt="Elm mail reader" title="Elm mail reader"></p><p><img src="https://opensource.com/sites/default/files/u128651/emacs19.png" alt="GNU Emacs programmable editor" title="GNU Emacs programmable editor"></p><p>SLS 1.05 甚至包含了一個可以讓你在終端玩的俄羅斯方塊版本。</p><p><img src="https://opensource.com/sites/default/files/u128651/tetris.png" alt="Tetris for terminals" title="Tetris for terminals"></p><p>在二十世紀 90 年代，多數住宅的網絡接入是通過撥號連接的，所以 SLS 1.05 包含了 Minicom 調製解調器撥號程序。Minicom 提供一個與調製解調器的直接連接，並需要用户通過賀氏調製解調器的 <strong>AT</strong> 命令來完成一些像是撥號或掛電話這樣的基礎功能。Minicom 同樣支持宏和其他簡單功能來使連接你的本地調製解調器池更容易。</p><p><img src="https://opensource.com/sites/default/files/u128651/minicom.png" alt="Minicom modem-dialer application" title="Minicom modem-dialer application"></p><p>但如果你想要寫一篇文檔時怎麼辦？ SLS 1.05 的存在要比 LibreOffice 或者 OpenOffice 早很長時間。在二十世紀 90 年代，Linux 還沒有這些應用。相反，如果你想要使用一個文字處理器，可能需要引導你的系統進入 MS-DOS，然後運行你喜歡的文字處理器程序，如 WordPerfect 或者共享軟件 GalaxyWrite。</p><p>但是所有的 Unix 系統都包含一套簡單的文本格式化程序，叫做 nroff 和 troff。在 Linux 系統中，他們被合併成 GNU groff 包，而 SLS 1.05 包含了 groff 的一個版本。我在 SLS 1.05 上的一項測試就是用 nroff 生成一個簡單的文本文檔。</p><p><img src="https://opensource.com/sites/default/files/u128651/paper-me-emacs.png" alt="A simple nroff text document" title="A simple nroff text document"></p><p><img src="https://opensource.com/sites/default/files/u128651/paper-me-out.png" alt="nroff text document output" title="nroff text document output"></p><h3 id="運行-x-windows" tabindex="-1">運行 X windows <a class="header-anchor" href="#運行-x-windows" aria-label="Permalink to “運行 X windows”">​</a></h3><p>獲取安裝 X windows 並不特別容易，如 SLS 安裝文件承諾的那樣：</p><blockquote><p>在你的 PC 上獲取安裝 X windows 可能會有一些發人深省的體驗，主要是因為 PC 的顯示卡類型太多。Linux X11 僅支持 VGA 類型的顯示卡，但在許多類型的 VGA 中僅有個別的某些類型是完全支持的。SLS 存在兩種 X windows 服務器。全綵的 XFree86，支持一些或所有 ET3000、ET400、PVGA1、GVGA、Trident、S3、8514、Accelerated cards、ATI plus 等。</p><p>另一個服務器 XF86_Mono，能夠工作在幾乎所有的 VGA 卡上，但只提供單色模式。因此，相比於彩色服務器，它會佔用更少的內存並擁有更快的速度。當然就是看起來不怎麼漂亮。</p><p>X windows 的配置信息都堆放在目錄 “/usr/X386/lib/X11/”。需要注意的是，“Xconfig” 文件為監視器和顯示卡定義了時序。默認情況下，X windows 設置使用彩色服務器，如果彩色服務器出現問題，你可以切換到單色服務器 x386mono，因為它已經支持各種標準的 VGA。本質上，這只是將 /usr/X386/bin/X 鏈接到它。</p><p>只需要編輯 Xconfig 來設置鼠標驅動類型和時序，然後鍵入 “startx” 即可。</p></blockquote><p>這些聽起來令人困惑，但它就是這樣。手工配置 X windows 真的可以是一個發人深省的體驗。幸好，SLS 1.05 包含了 syssetup 程序來幫你確定系統組件的種類，包括了 X windows 的顯示設置。在一些提示過後，經過一些實驗和調整，最終我成功啓動了 X windows！</p><p><img src="https://opensource.com/sites/default/files/u128651/syssetup.png" alt="The syssetup program" title="The syssetup program"></p><p>但這是來自於 1994 年的 X windows，它仍然並沒有桌面的概念。我可以從 FVWM （一個虛擬窗口管理器）或 TWM （選項卡式的窗口管理器）中選擇。TWM 直觀地設置提供一個功能簡單的圖形環境。</p><p><img src="https://opensource.com/sites/default/files/u128651/twm_720.png" alt="TWM" title="TWM"></p><h3 id="關機" tabindex="-1">關機 <a class="header-anchor" href="#關機" aria-label="Permalink to “關機”">​</a></h3><p>我已經在我的 Linux 尋根之旅沉浸許久，是時候最終回到我的現代桌面上了。最初我跑 Linux 的是一台僅有 8MB 內存和 一個 120MB 硬盤驅動器的 32 位 386 電腦，而我現在的系統已經足夠強大了。擁有雙核 64 位 Intel Core i5 處理器，4 GB 內存和一個 128 GB 的固態硬盤，我可以在我的運行着 Linux 內核 4.11.11 的系統上做更多事情。那麼，在我的 SLS 1.05 的實驗結束之後，是時候離開了。</p><p><img src="https://opensource.com/sites/default/files/u128651/shutdown-h.png" alt="Shutting down" title="Shutting down"></p><p>再見，Linux 1.0。很高興看到你的茁壯成長。</p>',23)),e("p",null,[t[27]||(t[27]=i("（題圖：圖片來源：",-1)),o(n,{href:"https://www.flickr.com/photos/litlnemo/19777182/"},{default:s(()=>[...t[25]||(t[25]=[i("litlnemo",-1)])]),_:1}),t[28]||(t[28]=i("。由 Opnesource.com 修改。",-1)),o(n,{href:"https://creativecommons.org/licenses/by-sa/2.0/"},{default:s(()=>[...t[26]||(t[26]=[i("CC BY-SA 2.0.",-1)])]),_:1}),t[29]||(t[29]=i("）",-1))]),t[51]||(t[51]=e("hr",null,null,-1)),e("p",null,[t[31]||(t[31]=i("via: ",-1)),o(n,{href:"https://opensource.com/article/17/8/linux-anniversary"},{default:s(()=>[...t[30]||(t[30]=[i("https://opensource.com/article/17/8/linux-anniversary",-1)])]),_:1})]),e("p",null,[t[35]||(t[35]=i("作者：",-1)),o(n,{href:"https://opensource.com/users/jim-hall"},{default:s(()=>[...t[32]||(t[32]=[i("Jim Hall",-1)])]),_:1}),t[36]||(t[36]=i(" 譯者：",-1)),o(n,{href:"https://github.com/softpaopao"},{default:s(()=>[...t[33]||(t[33]=[i("softpaopao",-1)])]),_:1}),t[37]||(t[37]=i(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[34]||(t[34]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[40]||(t[40]=i("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[38]||(t[38]=[i("LCTT",-1)])]),_:1}),t[41]||(t[41]=i(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:s(()=>[...t[39]||(t[39]=[i("Linux中國",-1)])]),_:1}),t[42]||(t[42]=i(" 榮譽推出",-1))])])}const k=p(m,[["render",d]]);export{b as __pageData,k as default};
